import{_ as l,l as r,o as e,c as h,v as i,p as n,x as o,d as s,i as E,S as A}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"High-NA 套刻","description":"","frontmatter":{"title":"High-NA 套刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-na-overlay-na.md","filePath":"litho/high-na-overlay-na.md","lastUpdated":1789023840000}'),p={name:"litho/high-na-overlay-na.md"};function d(c,a,B,N,g,m){const t=r("Mermaid");return e(),h("div",null,[a[1]||(a[1]=i('<h1 id="high-na-套刻" tabindex="-1">High-NA 套刻 <a class="header-anchor" href="#high-na-套刻" aria-label="Permalink to &quot;High-NA 套刻&quot;">​</a></h1><div class="epigraph"><p>0.55 把套刻预算收得更紧：半场拼接要场间对准，更薄焦深和变形光学把残差放大成 CD 与通孔覆盖失效。</p><footer>—— 归纳自 ASML 对 High-NA / EXE 套刻与拼接挑战的公开描述</footer></div><p><a href="/litho/high-na-stitch">上一课</a>把大 die 写成两次半场曝光和一条缝。缺口是：缝上的场间对准只是套刻账的一页——层间 overlay、匹配机台、变形畸变和离焦引起的表观位移，在 NA 0.55 下同时变苛刻。本课钉 High-NA 套刻。胶厚与焦深如何抢同一段 \\(z\\) 预算，留给<a href="/litho/high-na-resist-budget">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/litho-overlay">套刻</a> 的定义没变：本层相对下层（或同层另一次曝光）的位置残差。变的是公差与来源权重。节距随 0.55/0.33 约缩到 60%，通孔覆盖窗口按面积更苛刻。拼接引入「场 A 对场 B」这一项，NXE 全场产品没有。变形光学让 X/Y 倍率不同，畸变、放大和扫描同步误差要分轴建模，不能用各向同性 4× 的高阶 overlay 多项式原样搬过来。</p><p>ASML 公开把 overlay 与 stitching 写成 High-NA 量产导入的核心挑战之一，与源功率、pellicle、胶并列，而不是「NA 高了自然更准」。本课描述这条挑战结构，不编造 EXE 的纳米规格表。</p><h3 id="焦深把套刻和-cd-焊在一起" tabindex="-1">焦深把套刻和 CD 焊在一起 <a class="header-anchor" href="#焦深把套刻和-cd-焊在一起" aria-label="Permalink to &quot;焦深把套刻和 CD 焊在一起&quot;">​</a></h3><p>DOF \\(\\propto\\lambda/\\mathrm{NA}^2\\)，0.55 相对 0.33 大约按 \\((0.33/0.55)^2\\approx 0.36\\) 变薄。硅片不平整、卡盘指纹、掩模热，都会让局部离焦。非理想远心或残差倾斜时，离焦表现为 CD 兼表观位移。High-NA 上「只看 overlay 标记、不问焦」会漏掉通孔覆盖的真实失效。磁浮台与调焦带宽必须进入同一份预算。</p><p><span class="marginnote">单机套刻、匹配套刻、产品上套刻三种定义仍然适用。High-NA 导入期最容易把开发机上的单机数当成 HVM 产品上套刻。公开挑战描述针对的是后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对准传感器、编码器网格和双台策略继承真空 Twinscan，但网格密度、热校正和变形场模型按 EXE 重写。拼接层：先套下层，再套邻场，校正环要能同时收平移/放大/旋转与缝上的高阶跳变。交叉匹配：同一节点里 NXE 与 EXE 混跑时，DUV–EUV 那套 cross-match 还要加上 0.33–0.55 的光学指纹差。</p><p>计量：缝上专用标记、场内高阶、以及与 CD-SEM 的覆盖相关性。只优化标记 overlay 而通孔链失效，说明标记与器件的 M3D/阴影不同——<a href="/litho/euv-oblique-shadow">斜入射</a> 的警告在 0.55 更重。计算光刻把 overlay 残差当作热点输入，而不是假设缝上残差为零。</p><h3 id="拼接项与层间项分账" tabindex="-1">拼接项与层间项分账 <a class="header-anchor" href="#拼接项与层间项分账" aria-label="Permalink to &quot;拼接项与层间项分账&quot;">​</a></h3><p>场间（stitch）overlay 坏，同一层金属在缝上错位或双线。层间 overlay 坏，通孔落在下层线外。两者可以同时超，来源不同：前者是两次半场的对准与掩模匹配；后者含工艺变形、下层标记质量和镜头匹配。预算必须拆开，否则会拧错校正。</p>',14)),(e(),n(A,null,{default:o(()=>[E(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%8D%8A%E5%9C%BA%E6%8B%BC%E6%8E%A5%E5%9C%BA%E9%97%B4%22%5D%20--%3E%20OV%5B%22%E4%BA%A7%E5%93%81%E4%B8%8A%E5%A5%97%E5%88%BB%22%5D%0A%20%20IL%5B%22%E5%B1%82%E9%97%B4%E5%AF%B9%E5%87%86%22%5D%20--%3E%20OV%0A%20%20NA%5B%22NA%200.55%20%E6%9B%B4%E8%96%84%20DOF%22%5D%20--%3E%20APP%5B%22%E7%A6%BB%E7%84%A6%E8%A1%A8%E8%A7%82%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20AN%5B%22%E5%8F%98%E5%BD%A2%E5%88%86%E8%BD%B4%E7%95%B8%E5%8F%98%22%5D%20--%3E%20OV%0A%20%20APP%20--%3E%20OV%0A%20%20OV%20--%3E%20Y%5B%22%E9%80%9A%E5%AD%94%E8%A6%86%E7%9B%96%20%2F%20%E7%BC%9D%E4%B8%8A%E8%BF%9E%E7%BB%AD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更高 NA 提高光学对比，有助于某些层的套准读出，但目标图形更小，同样纳米残差的相对伤害更大。变形使扫描向与狭缝向的掩模台速度比不同（4× vs 8× 几何），同步误差投影到硅片时分轴加权。热：更大镜子、更高功率密度，掩模与镜头漂移更快，动态 overlay 进扫描。随机孔位置抖动看起来像 overlay，根子是光子/化学，修对准网格无效。</p><p>工厂经济：High-NA 单次省下的双重套刻层，可能被拼接层和更严的产品上套刻部分吃回。ASML 的公开叙事是挑战可管理、需整机与工艺一起资格认证，而不是「0.55 自动优于双重 0.33 的套刻」。</p><p><span class="marginnote">不要把 NXT 浸没产品页上的 overlay 纳米数抄到 EXE 上当结论。平台、真空、变形、半场都不同。本课只用公开的挑战描述：拼接 + 更高 NA + 更薄焦深。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不编造 EXE:5000/5200 的 overlay 规格，不把投资者日上某一代配置产能与套刻捆成课后答案。也不重写对准传感器光学。后课默认：说到 High-NA 良率，套刻账含缝、层间、分轴畸变和离焦耦合。胶厚预算从焦深侧再切一刀。</p><p>出处：ASML High-NA / EXE 对 overlay 与 stitching 的公开挑战描述；van Schoot 场几何；套刻定义见 overlay 课。磁浮台细节见已有工件台课。</p><p><span class="marginnote">芯粒若避开拼接，场间项消失，层间与 DOF 项仍在。套刻挑战不是「只有大芯片才有」，只是大芯片多一页缝。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>High-NA 套刻在更小节距上更苛刻，并新增半场场间项。</li><li>变形光学要求分轴畸变与同步模型，不能搬 NXE 各向同性多项式。</li><li>更薄焦深让离焦变成 CD 与表观位移，必须与 overlay 联立。</li><li>拼接项与层间项分账；随机孔抖不是对准能修的。</li><li>不编造 EXE 纳米规格；下一课从胶厚抢 DOF 写起。</li><li>出处：ASML EXE / High-NA 公开挑战描述；van Schoot。</li></ul>',10))])}const v=l(p,[["render",d]]);export{D as __pageData,v as default};
